$(document).ready(initialize_moment);
$(document).on('page:load', initialize_moment);
$(document).on('turbolinks:load', initialize_moment);

function initialize_moment() {
  moment.locale('en', {
    meridiem: function (hour, minute, isLowercase) {
      if( hour >= 12 )
        return isLowercase ? 'p.m.' : 'P.M.';
      else
        return isLowercase ? 'a.m.' : 'A.M.';
    }
  });
}

