Box.Application.addModule('address-feedback-component', function(context) {
  'use strict';

  var $component = $(context.getElement()),
      $verify    = $component.find('.address-verification-container'),
      $error     = $component.find('.address-error-container'),
      $spinner   = $component.find('.spinner'),
      address1   = null,
      address2   = null,
      city       = null,
      state      = null,
      zip5       = null,
      zip4       = null;

  function marshallAddress() {
    return({ address1 : address1,
             address2 : address2,
             city     : city,
             state    : state,
             zip5     : zip5,
             zip4     : zip4 });
  }

  function storeAddress(address) {
    address1 = address['address1'];
    address2 = address['address2'];
    city     = address['city'];
    state    = address['state'];
    zip5     = address['zip5'];
    zip4     = address['zip4'];
  }

  function loadAddress() {
    var displayAddress = $([
      '<p class="address1">' + address1 + '</p>',
      '<p class="address2">' + address2 + '</p>',
      '<p class="line-3">',
        '<span class="city">'  + city  + '</span>',
        '<span class="state">' + state + '</span>',
        '<span class="zip5">'  + zip5 + "-" + zip4  + '</span>',
      '</p>'].join("\n"));

    $component.find('.address-section').html(displayAddress);
  }

  function fillInAddress(response) {
    storeAddress(response['data'][0]);
    loadAddress();
    hideFeedback();
    showVerify();
  }

  function registerError(response) {
    $error.find('.error-value').text(response.data.error);
    hideFeedback();
    showError();
  }

  function hideFeedback() {
    $component.hide();
    $error.hide();
    $verify.hide();
  }

  function showError() {
    $component.show();
    $error.show();
  }

  function showVerify() {
    $component.show();
    $verify.show();
  }

  function processingRequest() {
    hideFeedback();
    $component.show();
    $spinner.show();
  }

  function changeAddress() {
    context.broadcast("selectAddress", { data: marshallAddress(), parent: $component.parent() });
  }

  function hideSpinner() {
    $spinner.hide();
  }

  function sameParent(node) {
    return ($(node)[0] == $component.parent()[0]);
  }

  return {
    init: function() {
      hideFeedback();
      hideSpinner();
    },

    onclick: function(event, element, elementType) {
      event.preventDefault();
      if(elementType === "change-address") { changeAddress(); hideFeedback();}
    },

    messages: [ 'verifiedAddress', 'unverifiedAddress', 'producingRequest', 'hideAllFeedback' ],

    onmessage: function(name, data) {
      if(name === 'hideAllFeedback'){
        $('.feedback').hide();
      } else if (sameParent(data['parent'])){
        hideSpinner();
        if(name === 'verifiedAddress') {
          fillInAddress(data);
        } else if(name === 'unverifiedAddress') {
          registerError(data);
        } else if(name === 'producingRequest') {
          processingRequest();
        }
      }
    }
  }
});
Box.Application.addModule('alerts-r-us-global-container', function (context) {
  'use strict';

  var $component = $(context.getElement());
  var $ajax_request;

  function showAlerts(alerts) {
    $component.html(buildAlerts(alerts));
  }

  function fetchAlerts(url) {
    $ajax_request = $.ajax({
      dataType: "json",
      type: "GET",
      url: url,
    })
      .done(function (data) {
        if (data.length > 0) {
          showAlerts(data)
        }
      })
      .fail(function () {
        return;
      });

    return $ajax_request
  }

  function buildAlerts(alerts) {
    return alerts.map(alert => {
      var isCollapsed = window.localStorage.getItem(alert.key) === 'collapsed';

      if (isCollapsed) { return }

      return `<div class="uscis-global-alert-${alert.variant.toLowerCase()}" key="${alert.key}">` +
        '  <div class="wrapper uscis-global-alert">' +
        '    <div class="uscis-global-alert-title-and-content-wrapper">' +
        `      <p class="uscis-global-alert-title">${alert.header}</p>` +
        `      <div class="uscis-global-alert-content">${alert.body}</div>` +
        '    </div>' +
        `    <a class="uscis-global-alert-dismiss" aria-label="Dismiss '${alert.header}' Alert" href="#" data-type="dismiss-alert"><span>Dismiss</span></a>` +
        '  </div>' +
        '</div>';
    });
  }

  return {
    init: function () {
      var url = '/alerts-r-us/retrieve-global-alerts'
      fetchAlerts(url);
    },
    onclick: function (event, element, elementType) {
      if (elementType === "dismiss-alert") {
        event.preventDefault();

        var alert = event.target.parentElement.parentElement.parentElement;
        var alertKey = alert.getAttribute('key');

        if (!alertKey) { // Needed to handle focus + enter key usage. Box.Application doesn't distinguish between enter key and a click here
          alert = event.target.parentElement.parentElement
          alertKey = alert.getAttribute('key');
        }

        window.localStorage.setItem(alertKey, 'collapsed');
        alert.style.display = 'none'
      }
    },
  };
});
Box.Application.addModule('form-navigation', function(context) {
  'use strict';

  var $component = $(context.getElement());

  function show_menu($element) {
    var $li_item = $element.closest('li');
    $li_item.toggleClass('open');

    if($li_item.hasClass('open')) {
      $element.text('Hide menu');
    } else {
      $element.text('Show menu');
    }
    
    $li_item.siblings().toggle();
  }

  function show_sub_menu($element) {
    var $parent_li = $element.closest('li');
    var $sub_menu =  $parent_li.find('.form-menu-sub');

    if($parent_li.hasClass('no-sub-nav')) {
      context.broadcast('form_navigation_click', { form: $element.closest('form') });
      return;
    } else {
      event.preventDefault();
      $sub_menu.toggleClass('active');
      $parent_li.toggleClass('open');     
    }

  }

  return {
    init: function() {
    },

    onclick: function(event, element, elementType) {
      if(!is_mobile()) {
        context.broadcast('form_navigation_click', { form: $(element).closest('form') });
        return;
      }

      var $element = $(element);

      if(elementType === 'show-menu') {
        show_menu($element);
      } else if(elementType === 'show-sub-menu') {
        show_sub_menu($element);
      } else {
        context.broadcast('form_navigation_click', { form: $(element).closest('form') });
      }
    }
  }
});
Box.Application.addModule('myuscis-address-component', function(context) {
  'use strict';

  var $component = $(context.getElement());
  var $address = $component.find('.uscis_address');  // address-input
  var $search_input = $component.find('.uscis_select_remote[data-type="country"]');
  if ($search_input.val() === undefined) {
    $search_input = $component.find('.uscis_collection_select[data-type="country"]');
  }
  var $countries = null;
  var $feedback = $component.find('#address-feedback');
  var $verify = $feedback.find('#address-verification-container');
  var $error = $feedback.find('#address-error-container');
  var $spinner = $feedback.find('.spinner');
  var $ajax_request;

  function validate_country() {
    var found = false;
    $.each($countries.index.datums, function(index, value) {
      found = found || value.name.toUpperCase() == $search_input.val().toUpperCase();
    });
    if(!found) {
      $search_input.val('');
    }
  }

  function is_domestic_address() {
    if ($search_input.data('foreign') === true) {
      return false;
    }

    if(!$search_input.length || !$search_input.val()) {
      return true;
    }

    return $search_input.val().toUpperCase().indexOf('USA') >= 0 || $.trim($search_input.val()).length == 0;
  }

  function swap_international_address(clearValues) {
    var $international = $component.find('[class$="international_locality"]');
    var $domestic = $component.find('select.uscis-collection-select.state,input.zip_code,input.county');
    var $shared = $component.find('input.address_line_one,input.address_line_two,input.city');

    if(is_domestic_address()) {
      if(clearValues){
        $international.find('input').val('');
        $shared.val('');
      }
      $international.hide();
      $.map($domestic, function(input){
        $(input).closest('.uscis-component').show();
      });
    } else {
      if(clearValues){
        $domestic.val('');
        $domestic.filter('select.uscis-collection-select')[0].selectize.clear();
        $international.find('input').val('');
        $shared.val('');
      }
      $domestic.closest('.uscis-component').hide();
      $international.show();
    }
    $feedback.hide();
  }

  function ajax_request_in_process() {
    if(!$ajax_request || $ajax_request.readyState == 4) {
      return false;
    }
    return true;
  }

  function address_filled_in() {
    return $component.find('.address_line_one').val() && $component.find('.city').val() &&
      $component.find('select.uscis-collection-select').val() &&
      $component.find('.zip_code').val();
  }

  function verify_domestic_address(elm) {
    if(!is_domestic_address() || !address_filled_in()) {
      return;
    }

    if(typeof elm === "undefined" || elm.data('verify') != true) {
      return;
    }

    if(ajax_request_in_process()) {
      $ajax_request.abort();
    }

    retrieve_suggestions();
  }

  function show_loading() {
    $feedback.show();
    $verify.hide();
    $error.hide();
    $spinner.html(buildSpinnerHtml);
    $spinner.show();

    focusOnFeedback();
  }

  function show_results(address) {
    $spinner.hide();
    $verify.html(buildAddressVerificationHtml);
    $verify.show();

    if(address['return_text'].length > 0) {
      $verify.find('uscis-alert-title').html(address['return_text']);
      $feedback.addClass('uscis-alert-warning');
    } else {
      $feedback.addClass('uscis-alert-neutral');
      $verify.find('uscis-alert-title').html('Confirm that the U.S. Postal Service address below is correct.');
    }

    $verify.find('#address1').html(address['address1']);
    $verify.find('#address2').html(' ' + address['address2']);
    $verify.find('#city').html(address['city'] + ' ');
    $verify.find('#state').html(address['state'] + ' ');
    if(address['zip4'] !== ''){
      $verify.find('#zip').html(address['zip5'] + '-' + address['zip4']);
    }else{
      $verify.find('#zip').html(address['zip5']);
    }
    
    
    focusOnFeedback();
  }

  function show_error(error_message) {
    $spinner.hide();
    $feedback.addClass('uscis-alert-warning');
    $error.html(buildAddressErrorHtml);
    $error.find('#error-value').html(error_message);
    $error.show();

    focusOnFeedback();
  }

  function use_suggested_address() {
    $component.find('.address_line_one').val($verify.find('#address1').html());
    $component.find('.address_line_two').val($verify.find('#address2').html().trim());
    $component.find('.city').val($verify.find('#city').html().trim());
    $component.find('.zip_code').val($verify.find('#zip').html());
    var $select = $component.find('select.uscis-collection-select.state')[0].selectize;
    $select.setValue($verify.find('#state').html().trim());
    context.broadcast('force_address_change_event', $address);
  }

  function create_address_query() {
    var zip = $component.find('.zip_code').val();
    zip = zip.indexOf("-") >= 0 ? zip.split("-")[0] : zip;
    return { address1: $component.find('.address_line_one').val(),
             address2: $component.find('.address_line_two').val(),
                    city : $component.find('.city').val(),
                    state : $component.find('select.uscis-collection-select.state').val(),
                    zip5 : zip };
  }

  function retrieve_suggestions() {
    var address = create_address_query();
    $feedback.removeClass('uscis-alert-neutral');
    $feedback.removeClass('uscis-alert-warning');
    $component.tabIndex = 0;

    $ajax_request = $.ajax({
      dataType: "json",
      type: "POST",
      url: "/external/public/api/v1/usps/address_standardization",
      data: address,
      beforeSend: function() {
        show_loading();
      }})
      .done(function(data) {
        if (data.results) {
          show_results(data.results[0]);
        } else {
          show_error(data.error);
        }
        $feedback.focus()
      })
      .fail(function(jqXHR, textStatus) {
        if (jqXHR.status === 401) {
          window.location.href = '/logout';
          return;
        }
      });
    return $ajax_request
  }

  function focusOnFeedback() {
    //Look for a better way to accomplish not focusing on
    //the alert and skipping over county.
    if ($address.find('.county').length === 0) {
      $component.focus();
    }
  }

  function toggle_address_component(){
    $address.find('.uscis-address-wrapper').toggle();
  }

  function buildSpinnerHtml() {
    return  '<span class="fa fa-refresh fa-spin"></span>' +
            '<span class="with-margin-left-15">We are connecting to the U.S. Postal Service to validate your address.</span>';
  }

  function buildAddressVerificationHtml() {
    return  '<div id="address-verification-top">' +
            ' <p class="uscis-alert-title"><b>Confirm that the U.S. Postal Service address below is correct</b></p>' +
            ' <div id="address-section" class="uscis-alert-content">' +
            '   <p id="address-line"><span id="address1"></span><span id="address2"></span></p>' +
            '   <p id="line-3"><span id="city"></span><span id="state"></span><span id="zip"></span></p>' +
            ' </div>' +
            '</div>' +
            '<div id="address-verification-bottom">' +
            '  <div class="action-section">' +
            '    <div class="uscis-alert-buttons">' +
            '     <a class="uscis-button uscis-button-blue" href="#" data-type="change-address">Yes, use this address</a>' +
            '     <a class="uscis-button uscis-button-clear" href="#" data-type="close-feedback">No, use what I entered</a>' +
            '    </div>' +
            '  </div>' +
            '</div>';
  }

  function buildAddressErrorHtml() {
    return  '<div id="address-verification-top">' +
            '  <p class="uscis-alert-title"><b>The following error was given based on the address you entered</b></p>' +
            '  <p class="uscis-alert-content" id="error-value"></p>' +
            '</div>' +
            '<div id="address-verification-bottom">' +
            '  <div class="uscis-alert-buttons">' +
            '    <button name="button" type="submit" class="uscis-button uscis-button-blue" data-type="close-feedback">Close this error</button>' +
            '  </div>' +
            '</div>';
  }

  return {
    messages: ['dynamic-country-selection', 'select-built'],
    behaviors: ['alert', 'help-text'],

    init: function() {
      swap_international_address();
    },
    onclick: function(event, element, elementType) {
      if(elementType === "change-address") {
        event.preventDefault();
        use_suggested_address();
        $feedback.hide();
        $feedback.removeClass('uscis-alert-warning');
        $feedback.removeClass('uscis-alert-neutral');
      }
      else if(elementType === "close-feedback") {
        event.preventDefault();
        $feedback.hide();
        $feedback.removeClass('uscis-alert-warning');
        $feedback.removeClass('uscis-alert-neutral');
      }
      else if(elementType === 'hide-address') {
        toggle_address_component();
      }
    },
    onfocusout: function(event, element, elementType) {
      if(elementType === 'country') {
        swap_international_address(true);
      }
    },
    onchange: function(event, element, elementType) {
      if ( !$(element).is(':disabled, [readonly]') ) {
        switch(elementType) {
          case 'country':
            swap_international_address(true);
            break;
          case 'street':
          case 'city':
          case 'state':
            if(!address_filled_in()) { break; }
          case 'zip':
            verify_domestic_address($(element));
            break;
        }
      }
    },
    onmessage: function(event, data) {
      if (event == 'dynamic-country-selection' || event == 'select-built') {
        swap_international_address();
      }
    }
  }
});
Box.Application.addModule('myuscis-country-component', function(context) {
  'use strict';

  var $component = $(context.getElement());
  var $search_input = $component.find('.country');
  var $country_of_birth_input = $component.find('#form_data_country_of_birth');
  var $current_country_of_birth = $component.find($('input[id*="form_data_current_prior_spouse_country_"]'));
  var $prior_country_of_birth = $component.find($('input[id*="form_data_prior_spouse_country_"]'));
  var $countries = null;

  function validate_country() {
    var found = false;
    $.each($countries.index.datums, function(index, value) {
      found = found || value.name.toUpperCase() == $search_input.val().toUpperCase();
    });
    if(!found) {
      $search_input.val('');
    }
  }

  function load_countries(url) {
    $countries = new Bloodhound({
      datumTokenizer: Bloodhound.tokenizers.obj.whitespace('name'),
      queryTokenizer: Bloodhound.tokenizers.whitespace,
      prefetch: {
        ttl: 3600000, // cache requests for one hour
        url: url,
        filter: function(response) {
          return $.map(response, function(country) { return { name: country.value, typeCode: country.typeCode }; });
        }
      }
    });
    $countries.initialize();
    return $countries;
  }

  function setup_autocomplete(url) {
    $search_input.typeahead({
      hint: true,
      highlight: true,
      minLength: 1
    }, {
      name: 'countries',
      displayKey: 'name',
      source: load_countries(url).ttAdapter()
    }).on('typeahead:selected', function(event, data) {
      $search_input.val(data.name);        
    }).blur(function() {
      validate_country($search_input);
    });
  }

  function set_country_url() {
   return ($country_of_birth_input.length > 0) || ($current_country_of_birth.length >0) || ($prior_country_of_birth.length >0)
    ? '/external/public/api/v1/birth_countries' : '/external/public/api/v1/countries';
  }

  return {
    init: function() {
      var url = set_country_url();
      setup_autocomplete(url);
    }
  }
});
Box.Application.addModule('uscis-accordion', function(context) {
  'use strict';

  var $component = $(context.getElement());

  function toggle_accordion($item) {
    var $content = $item.find('.uscis-accordion-content');

    function setHeightToAuto() { $content.css('height', 'auto'); };

    $item.toggleClass('expanded');

    if($item.hasClass('expanded')) {
      // Use a fixed height so animations will work, then change to auto so the
      // container will resize for dynamic content
      $content.css('height', $content.prop('scrollHeight') + 'px');
      setTimeout(setHeightToAuto, 1000);

    } else {
      $content.css('height', '0');
    }

    toggle_title($item, '.uscis-accordion-title');
  }

  return {
    init: function() {
      var expanded = $component.data('expanded');

      if(expanded === undefined) {
        expanded = 'first';
      }

      expanded = expanded.toLowerCase();

      $component.find('.uscis-accordion-title').each(function() {
        $(this).attr('title', 'Show ' + $.trim($(this).text()));

        if(expanded == 'all') {
          toggle_accordion($(this).parent());
        }
      });

      if(expanded == 'first') {
        toggle_accordion($component.find('.uscis-accordion-item').first());
      }
    },

    onclick: function(event, element, elementType) {
      var $item  = $(event.target).parent();
      var $content = $(event.target).parents().filter('.uscis-accordion-content');

      if($(event.target).hasClass('uscis-accordion-title')) {
        event.preventDefault();
        toggle_accordion($item);
      }

      $content.attr('style', 'height: auto');

    }
  }
});
