Box.Application.addModule('uscis-collapsible-list', function(context) {
  'use strict';

  var $component = $(context.getElement());

  function toggle_collapsible_list($item) {
    var $content = $item.find('.uscis-collapsible-list-content');

    function setHeightToAuto() { $content.css('height', 'auto'); };

    $item.toggleClass('expanded');

    if($item.hasClass('expanded')) {
      $item.find('.uscis-collapsible-list-title').attr('aria-expanded', true);
      var offset = 0;

      if($item.hasClass('title--hidden-expanded')) {
        offset = 30;
      }

      // Use a fixed height so animations will work, then change to auto so the
      // container will resize for dynamic content
      $content.css('height', ($content.prop('scrollHeight') - offset) + 'px');
      setTimeout(setHeightToAuto, 1000);

    } else {
      $item.find('.uscis-collapsible-list-title').attr('aria-expanded', false);
      $content.css('height', '0');
    }

    toggle_title($item, '.uscis-collapsible-list-title');

    context.broadcast('refresh-waypoint');
  }

  return {
    init: function() {
      $component.find('.uscis-collapsible-list-title').each(function() {
        $(this).attr('title', 'Show ' + $.trim($(this).text()));
        $(this).attr('aria-expanded', false);
      });

      $component.find('.uscis-collapsible-list-item').each(function(index) {
        if($(this).data('expanded')) {
          toggle_collapsible_list($(this));
        }
      });
    },

    onclick: function(event, element, elementType) {

      if($(event.target).hasClass('disable-t3')) { return; }

      if($(event.target).hasClass('uscis-collapsible-list-title') ||
         $(event.target).closest('.uscis-collapsible-list-title').length > 0) {
        event.preventDefault();

        var $item  = $(event.target).closest('.uscis-collapsible-list-item');
        toggle_collapsible_list($item);
      }
    }
  }
});
Box.Application.addModule('uscis-collection-card', function(context) {
  'use strict';

  var $component = $(context.getElement());

  function toggle_background() {
    $('.uscis-collection-card-wrapper').find('input:checked').closest('.uscis-collection').addClass('collection-card-checked');
  }

  function equal_height_columns() {
    var maxHeight;

    $('.uscis-collection-card-wrapper .uscis-collection').each(function() {
      maxHeight = maxHeight > $(this).height() ? maxHeight : $(this).height();
    });

    $('.uscis-collection-card-wrapper .uscis-collection').each(function() {
      $(this).height(maxHeight);
    });
  }

  function bind_focus() {
    $('.uscis-collection').each(function(){
      var $box = $(this);
      var $input = $(this).find('input');
      $input.focus(function() {
        $box.addClass('focused');
      })
      $input.focusout(function() {
        $box.removeClass('focused');
      })
    });
  }

  return {
    init: function() {
      toggle_background();
      bind_focus();

      if($('.one-per-row').length == 0) {
        equal_height_columns();
      }
    },

    onclick: function(event, element, elementType) {
      var $item = $(event.target);

      if($item.hasClass('uscis-collection')) {
        $item.find('input[type="radio"]').prop('checked', 'checked');

        var cbx = $item.find('input[type="checkbox"]');

        if(cbx) {
          $item.find('input[type="checkbox"]').prop('checked', !cbx.prop("checked"));
        }
      }

      $('.uscis-collection').removeClass('collection-card-checked');
      toggle_background();
    }
  }
});
// data-module: uscis-copy-address
// use this to copy address inputs on the same page
Box.Application.addModule('uscis-copy-address', function(context) {
  'use strict';

  var $component,
      input_service,
      exclude_selector;

  function copy_data($checkbox) {
    copy_select($checkbox);
    copy_input($checkbox);
    context.broadcast('hideAllFeedback');
    context.broadcast('dynamic-country-selection');
  }

  function copy_input($checkbox) {
    var contains_id = get_target_field($checkbox);
    var $inputs = $('input[id*=' + contains_id + ']:not(:checkbox)');
    if(exclude_selector){
      $inputs = $inputs.not('input[id*=' + exclude_selector + ']');
    }

    $inputs.each(function(idx, elm) {
      var $target = $(elm);
      
      if($target.attr('id').indexOf('source') == -1) {
        if($checkbox.is(':checked')) {
          input_service.disable_input($target);
          var $source = get_source_input($checkbox, $target);
          $target.val($source.val());
        } else {
          $target.val('');
          input_service.enable_input($target);
        }
      }
    });
  }

  function copy_select($checkbox) {
    var contains_id = get_target_field($checkbox);
    var $selects = $('select[id*=' + contains_id + ']');
    if(exclude_selector){
      $selects = $selects.not('select[id*=' + exclude_selector + ']');
    }

    $selects.each(function(idx, elm) {
      var $target = $(elm)[0].selectize;

      if($target) {
        if($checkbox.is(':checked')) {
          input_service.disable_select($(elm));
          var $source = get_source_input($checkbox, $(elm));
          $target.setValue($source.val(), true); // 'true' ensures that setValue doesn't fire off callbacks
        } else {
          $target.setValue('', true);
          input_service.enable_select($(elm));
        }
      }
    });
  }

  function get_target_field($input) {
    return $input.data('target');
  }

  function get_source_field($input) {
    return $input.data('source');
  }

  function get_source_input($checkbox, $input) {
    var target = get_target_field($checkbox);
    var source = get_source_field($checkbox);
    return $('#' + $input.attr('id').replace(target, source));
  }

  return {
    messages: ['select-built'],
    init: function() {
      $component = $(context.getElement()),
      input_service = context.getService('uscis-input-service'),
      exclude_selector = $component.data('exclude-ids-with');

      var $checkbox = $('input[data-module="uscis-copy-address"]');

      if($checkbox.is(':checked')) {
        copy_data($checkbox);
      }
    },
    onclick: function(event, element, element_type) {
      var $input = $(event.target);
      if($input.is(':checkbox')) {
        copy_data($input);
      }
    },
    onmessage: function(name, data) {
      if(name === 'select-built') {
        var $checkbox = $('input[data-module="uscis-copy-address"]');
        if($checkbox.is(':checked')) {
          copy_data($checkbox);
        }
      }
    }
  }
});

Box.Application.addModule('uscis-copy-external', function(context) {
  'use strict';

  var $component = $(context.getElement()),
      input_service = context.getService('uscis-input-service');

  function copy_data($input) {
    copy_select($input);
    copy_input($input);
    context.broadcast('hideAllFeedback');
    context.broadcast('dynamic-country-selection');
  }

  function copy_input($input) {
    var starts_with_id = get_target_input($input);
    var $inputs = $('input[id^=' + starts_with_id + ']:not(:checkbox)');
    
    $inputs.each(function(idx, elm) {
      var $target = $(elm);

      if($target.attr('id').indexOf('source') == -1) {
        if($input.is(':checked')) {
          input_service.disable_input($target);
          if($target.data('copy') != undefined) {
            $target.val($target.data('copy'));
          }
        } else {
          input_service.enable_input($target);
        }
      }
    });   
  }

  function get_target_input($input){
    return $input.attr('id').replace(/_checkbox[0-9]*/, '');
  }

  function copy_select($input) {
    var starts_with_id = get_target_input($input);
    var $selects = $('select[id^=' + starts_with_id + ']');

    $selects.each(function(idx, elm) {
      var $target = $(elm)[0].selectize;

      if($target) {
        if($input.is(':checked')) {
          input_service.disable_select($(elm));
          if($(elm).data('copy') != undefined) {
            $target.setValue($(elm).data('copy'));
          }
        } else {
          input_service.enable_select($(elm));
        }
      }
    });    
  }

  function build_copy_external() {
    $('input[data-module="uscis-copy-external"]').each(function(idx, elm) {
      copy_data($(elm));
    });

    context.broadcast('copy-external-complete');    
  }

  return {
    messages: ['select-built'],
    init: function() {
      build_copy_external();
    },
    onclick: function(event, element, element_type) {
      var $input = $(event.target);
      if($input.is(':checkbox')) {
        copy_data($input);
      } 
    },
    onmessage: function(name, data) {
     build_copy_external();
    }
  }
});

Box.Application.addModule('uscis-copy-page', function(context) {
  'use strict';

  var $component = $(context.getElement()),
    input_service = context.getService('uscis-input-service');

  function copy_data($input) {
    var $target = get_target_input($input);

    if($input.is(':checked')) {
      var $source = $("input[id$='" + $input.data('source')+ "']");

      if ($source.data('type') == 'visible_date'){
        disable_approximate_checkbox($target, true);
        update_target_with_mask($source);
      };

      input_service.disable_input($target);
      $target.val($source.val());
    } else {
      disable_approximate_checkbox($target, false);
      input_service.enable_input($target);
    }
  }

  function get_target_input($input) {
    return $('#' + $input.attr('id').replace(/_checkbox[0-9]*/, ''));
  }

  function update_targets($source) {
    var val = $source.val();

    $('input[data-source]').each(function(idx, elm) {
      var $target = $(elm);

      if($target.is(':checked')) {
        get_target_input($target).val(val);
      }
    });
  }

  function disable_approximate_checkbox(input, disabled_value){
    var apprx_checkbox = $('#'+ input.attr('id') + "_checkbox1");
    apprx_checkbox.attr('disabled', disabled_value);
  }

  function get_inputmask_from(source){
    if (source.attr('data-parsley-date') == "[\"M/YYYY\"]"){
      return { mask: "99/9999",
               placeholder: "MM/YYYY",
               clearMaskOnLostFocus: false,
               clearIncomplete: true }
    }
    else if(source.attr('data-parsley-date') == "[\"M/D/YYYY\"]"){
      return { alias: "mm/dd/yyyy",
               placeholder: "MM/DD/YYYY",
               clearMaskOnLostFocus: false,
               clearIncomplete: true }
    }
  }

  function update_target_with_mask($source){
    var source = $source;

    $('input[data-source]').each(function(idx, elm) {
      var $target = $(elm);
      var val = source.val();

      if($target.is(':checked')) {
        var $date = get_target_input($target);
        $date.inputmask(get_inputmask_from(source));
        $date.val(val);
      }
    });
  }

  return {
    init: function() {
      $('input[data-source]').each(function(idx, elm) {
        copy_data($(elm));
        var $source = $('#form_data_' + $(elm).data('source'));
        if ($source.data('type') == 'visible_date'){
          $($source.closest('.uscis-component')[0]).on('change', function(){
            update_target_with_mask($source);
          });
        };
        $source.on('keyup', function() {
          update_targets($source);
        });
      });
    },
    onclick: function(event, element, element_type) {
      var $input = $(event.target);
      if($input.is(':checkbox')) {
        copy_data($input);
      }
    }
  }
});
