function isDateValid(to_date, from_date, requirements, recheckToDate) {
  if (from_date != 'Invalid Date' && to_date != 'Invalid Date') {
    if (recheckToDate) {
      toDateRangeValidCheck(requirements);
    }
    return from_date < to_date;
  } else {
    return true;
  }
}

function toDateRangeValidCheck(requirements) {
  if ($(requirements).parsley().isValid()){
    $(requirements).closest('.uscis-inline-input').find('.parsley-error').remove();
    $(requirements).closest('.uscis-input-error').addClass('uscis-input-error').removeClass('uscis-input-error');
  }
}

function parsley_is_required(name, guid) {
  return window['parsley_conditionals'][name](guid);
}

var parsley_conditionals = window.parsley_conditionals || {};
parsley_conditionals.domesticaddress = function(guid) {
  // twitter typeahead clones the input except for the id attribute
  var form = $.find("[input-guid='" + guid + "']")[0].closest('form');
  var country_input = $(form).find('.country[id]');
  if(country_input.length == 0) {
    return true;
  }
  var country = country_input.val();
  return country == '' || country.toUpperCase() == 'UNITED STATES';
};

parsley_conditionals.condrequireddate = function(guid) {
  var form = $.find("[id='form_data_" + guid + "']")[0];
  if(form === undefined || form.value == "" || !window.ParsleyConfig.validators.date.fn(form.value)){
    return true;
  }
  return false;
};

function any_invalid_dates(first_date, second_date) {
  if (first_date == 'Invalid Date' || second_date == 'Invalid Date') {
    return true;
  }
}
;
function uscis_date_element_visible(field_instance) {
  return field_instance.$element.is(":visible");
}

function uscis_date_element(field_instance) {
  return field_instance.$element.hasClass('visible_date');
}

function uscis_hidden_date_element(field_instance) {
  return field_instance.$element.hasClass('hidden_date');
}

function is_uscis_date_range(field_instance) {
  return field_instance.$element.parents('.uscis_date_range').length > 0;
}

function remove_invalid_classes(field_instance) {
  field_instance.$element.closest('.uscis-collection-wrapper').removeClass('uscis-input-error');
  field_instance.$element.closest('.uscis-input-wrapper').find('.error-container .uscis-error').hide();
}

function find_other_hidden_date(field_instance) {
  return field_instance.$element.closest('.uscis-component').find('.hidden_date').filter(function(i) {
    return field_instance.$element[0] != this;
  });
}

function hidden_date_value_is_valid($hidden_date) {
  return $hidden_date.parsley().validate();
}

function other_hidden_date_is_valid(field_instance) {
  $hidden_date = find_other_hidden_date(field_instance);
  var result = true;
  var validations = $($hidden_date).parsley().constraints;
  $.each(validations, function() {
    result = result && this.fn($hidden_date.val(), this.requirements);
  });
  return result;
}

function validate_uscis_date_range(field_instance) {
  if(field_instance.validationResult == false || field_instance.validationResult.length > 0) { return; }
  if(!other_hidden_date_is_valid(field_instance)) { return; }

  var $other_hidden_date = find_other_hidden_date(field_instance);
  var $hidden_date = field_instance.$element;
  if(!date_range_is_valid($hidden_date, $other_hidden_date)) {
    field_instance.validationResult = false;
    window.ParsleyUI.addError(field_instance, 'date_range', 'This date range is not possible.');
  }
}

function date_range_is_valid($hidden_elm1, $hidden_elm2) {
  var m1 = moment($hidden_elm1.val(), "MM/DD/YYYY");
  var m2 = moment($hidden_elm2.val(), "MM/DD/YYYY");
  if($hidden_elm1.siblings('.visible_date').hasClass('date_from')) {
    return m1.isBefore(m2);
  } else {
    return m2.isBefore(m1);
  }
}
