$(document).ready(init_special_inputs);
$(document).on('page:load', init_special_inputs);

/*
 Find within the specified element.
 If the element is falsey (null, undefined) then default to searching within root ($).
 If the element is the root ($), return $.
 */
function find_within(element) {
  return element && element !== $ ? function (selector) {
    return $(selector, element);
  } : $;
}

function init_special_inputs(element) {
  init_phone_numbers(element);
  init_a_number(element);
  init_ssn(element);
  init_account_no(element);
  init_inputs(element);

  var $element = find_within(element);

  var dates = $element(".visible_date").filter(function () {
    return $(this).val() !== 'Present'; //exclude items using explicit "Present" value
  });

  $.each(dates, function(idx, date){
    var max_year = discover_max_year(date);
    $(date).inputmask({
      placeholder: "MM/DD/YYYY",
      clearMaskOnLostFocus: false,
      clearIncomplete: true,
      yearrange: { maxyear: max_year }
    });
  });

  $element("input.zip_code").inputmask({
    mask: ["99999", "99999-9999"],
    clearIncomplete: true,
    placeholder: "",
    greedy: false
  });
}

function discover_max_year(element){
  var max_year = moment();
  if ($(element).data('allow-future') === true && $(element).data('max-future-years') !== undefined){
    var max_future_years = $(element).data('max-future-years');
    max_year = moment().add(max_future_years, 'year');
  }
  return max_year.year();
}

function init_inputs(element) {
  var $element = find_within(element);
  $element("input[data-inputmask-regex], textarea[data-inputmask-regex]").inputmask('Regex',
    {
      onBeforeMask: function(value, opts) {
        // strip HTML tags
        return value.replaceAll(/(<\/?([^>]+)>)/ig, '');
      }
  });
}

function init_phone_numbers(element) {
  var $element = find_within(element);
  $element('input.phone-number, input.phone, input.phone_number').mask('(Z00) 000-0000', {
    translation: {
      'Z': {
        pattern: /[2-9]/
      }
    }
  });
}

function init_a_number(element) {
  var $element = find_within(element);
  $element('input.a-number, input.alien_number, input.a_number').blur(function () {
    var value = $(this).val();
    if (value.length == 7 && !has_leading_zeros(value)) {
      $(this).val('00' + value);
    }
    else if (value.length == 8 && !has_leading_zeros(value)) {
      $(this).val('0' + value);
    }
  }).mask("990000000");
}

function has_leading_zeros(val) {
  return val.charAt(0) == '0' && val.charAt(1) == '0';
}

function init_ssn(element) {
  var $element = find_within(element);
  $element('.ssn, .ssn_number').mask('000-00-0000');
}

function init_account_no(element) {
  var $element = find_within(element);
  $element('.uscis_number').mask('000000000000');
}
